def lens(ctx, target=".", args=None):
    import ast
    risky_call = "loads"
    items = []
    for rel in ctx.iter_py_files(target):
        src = ctx.read_text(rel)
        if not src:
            continue
        try:
            tree = ast.parse(src)
        except SyntaxError:
            continue
        for node in ast.walk(tree):
            if isinstance(node, ast.Subscript) and isinstance(node.value, ast.Call):
                fn = node.value.func
                if isinstance(fn, ast.Attribute) and fn.attr in ("get", risky_call):
                    items.append({"location": f"{rel}:{node.lineno}", "issue": f"unguarded_{fn.attr}_subscript"})
    return {"summary": f"Found {len(items)} unguarded .{risky_call}/get subscript(s).", "items": items[:15]}

def lens(ctx, target=".", args=None):
    import ast
    marker = "bare_except"
    items = []
    for rel in ctx.iter_py_files(target):
        src = ctx.read_text(rel)
        if not src:
            continue
        try:
            tree = ast.parse(src)
        except SyntaxError:
            continue
        for node in ast.walk(tree):
            if isinstance(node, ast.ExceptHandler):
                body = node.body or []
                is_pass = len(body) == 1 and isinstance(body[0], ast.Pass)
                if not body or is_pass:
                    kind = ast.unparse(node.type) if node.type is not None else marker
                    items.append({"location": f"{rel}:{node.lineno}", "exception": kind})
    return {"summary": f"Detected {len(items)} swallowed exception handler(s).", "items": items[:15]}

