def lens(ctx, target=".", args=None):
    import ast
    target_suffix = ".json"
    items = []
    for rel in ctx.iter_py_files(target):
        src = ctx.read_text(rel)
        if not src:
            continue
        try:
            tree = ast.parse(src)
        except SyntaxError:
            continue
        for node in ast.walk(tree):
            if isinstance(node, ast.Call) and isinstance(node.func, ast.Attribute) and node.func.attr == "write_text":
                line_txt = ast.unparse(node)
                if target_suffix in line_txt or "json.dumps" in line_txt:
                    items.append({"location": f"{rel}:{node.lineno}", "call": "direct_write_text_json"})
    return {"summary": f"Found {len(items)} direct {target_suffix} overwrite call(s).", "items": items[:15]}

def lens(ctx, target=".", args=None):
    import ast
    runner = "subprocess"
    items = []
    for rel in ctx.iter_py_files(target):
        src = ctx.read_text(rel)
        if not src:
            continue
        try:
            tree = ast.parse(src)
        except SyntaxError:
            continue
        for node in ast.walk(tree):
            if isinstance(node, ast.Call) and isinstance(node.func, ast.Attribute):
                if isinstance(node.func.value, ast.Name) and node.func.value.id == runner and node.func.attr == "run":
                    kw_names = {kw.arg for kw in node.keywords}
                    if "timeout" not in kw_names:
                        items.append({"location": f"{rel}:{node.lineno}", "issue": "missing_timeout"})
    return {"summary": f"Found {len(items)} {runner}.run call(s) without timeout.", "items": items[:15]}

def lens(ctx, target=".", args=None):
    import ast
    db_mod = "sqlite3"
    items = []
    for rel in ctx.iter_py_files(target):
        src = ctx.read_text(rel)
        if not src or db_mod not in src:
            continue
        try:
            tree = ast.parse(src)
        except SyntaxError:
            continue
        has_close = ".close(" in src
        for node in ast.walk(tree):
            if isinstance(node, ast.Call) and isinstance(node.func, ast.Attribute):
                if node.func.attr == "connect" and not has_close:
                    items.append({"location": f"{rel}:{node.lineno}", "issue": "connect_without_close"})
    return {"summary": f"Scanned {db_mod}; found {len(items)} potential unclosed handle(s).", "items": items[:15]}

def lens(ctx, target=".", args=None):
    import ast
    divisor_note = "unclamped_div"
    items = []
    for rel in ctx.iter_py_files(target):
        src = ctx.read_text(rel)
        if not src:
            continue
        try:
            tree = ast.parse(src)
        except SyntaxError:
            continue
        for node in ast.walk(tree):
            if isinstance(node, ast.BinOp) and isinstance(node.op, ast.Div):
                if isinstance(node.right, ast.Call) and isinstance(node.right.func, ast.Name) and node.right.func.id == "len":
                    items.append({"location": f"{rel}:{node.lineno}", "issue": divisor_note})
    return {"summary": f"Found {len(items)} raw /len(...) divisor site(s).", "items": items[:15]}
